const crypto = require('crypto');
const q = items[0].json.query || {};
const verifyToken = $env.WA_VERIFY_TOKEN || '';
const recebido = q['hub.verify_token'] || '';

let tokenBate = false;
try {
  const a = Buffer.from(recebido);
  const b = Buffer.from(verifyToken);
  tokenBate = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) {
  tokenBate = false;
}

const ok = q['hub.mode'] === 'subscribe' && tokenBate;
return [{ json: { ok, challenge: q['hub.challenge'] || '' } }];

const crypto = require('crypto');

const item = items[0];
const rawB64 = item.binary && item.binary.data ? item.binary.data.data : null;
const rawBody = rawB64 ? Buffer.from(rawB64, 'base64').toString('utf8') : null;

const headers = item.json.headers || {};
const sigHeader = (headers['x-hub-signature-256'] || '').toString();
const secret = $env.WA_APP_SECRET || '';

function verify() {
  if (rawBody === null) return false; // sem raw body não há como validar — falha fechado
  if (!sigHeader.startsWith('sha256=') || !secret) return false;
  const provided = sigHeader.slice('sha256='.length);
  let a, b;
  try {
    a = Buffer.from(provided, 'hex');
    b = crypto.createHmac('sha256', secret).update(rawBody).digest();
  } catch (e) {
    return false;
  }
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

const valid = verify();
let body = {};
try {
  body = item.json.body ?? JSON.parse(rawBody);
} catch (e) {
  body = {};
}

return [{ json: { valid, payloadRaw: body } }];

