const prev = $('Verificar Assinatura Meta').first().json;
const valid = prev.valid;
const body = prev.payloadRaw || {};

if (!valid) {
  return [{ json: { valid: false, sql: 'SELECT 0 AS no_op;', params: [], pausarCampanha: false } }];
}

const statuses = [];
for (const entry of (body.entry || [])) {
  for (const change of (entry.changes || [])) {
    for (const st of ((change.value && change.value.statuses) || [])) statuses.push(st);
  }
}

if (statuses.length === 0) {
  return [{ json: { valid: true, sql: 'SELECT 0 AS no_op;', params: [], pausarCampanha: false } }];
}

const CODIGOS_PERMANENTES = new Set(['131026']);
const CODIGOS_TEMPORARIOS = new Set(['131049', '130429']);
const CODIGOS_QUALIDADE = new Set(['131048']);

function backoffSql() {
  return `UPDATE envios SET
            status = CASE WHEN tentativas >= 5 THEN 'falha' ELSE 'pendente' END,
            erro_tipo = CASE WHEN tentativas >= 5 THEN 'permanente' ELSE 'temporario' END,
            erro_codigo = $2, erro_mensagem = $3,
            agendado_para = CASE tentativas
              WHEN 1 THEN now() + interval '5 minutes'
              WHEN 2 THEN now() + interval '15 minutes'
              WHEN 3 THEN now() + interval '1 hour'
              WHEN 4 THEN now() + interval '4 hours'
              ELSE now() + interval '12 hours'
            END,
            atualizado_em = now()
          WHERE provider_message_id = $1 AND canal = 'whatsapp' AND status NOT IN ('entregue','falha');`;
}

const out = [];
for (const st of statuses) {
  const providerMessageId = st.id;
  const status = st.status;
  const errorCode = (st.errors && st.errors[0]) ? String(st.errors[0].code) : null;
  const errorMsg = (st.errors && st.errors[0]) ? (st.errors[0].title || '') : null;

  let sql = 'SELECT 0 AS no_op;';
  let params = [];
  let pausarCampanha = false;

  if (status === 'delivered') {
    sql = `UPDATE envios SET status='entregue', entregue_em=now(), atualizado_em=now()
           WHERE provider_message_id=$1 AND canal='whatsapp' AND status NOT IN ('entregue','falha');`;
    params = [providerMessageId];
  } else if (status === 'failed' && errorCode) {
    if (CODIGOS_PERMANENTES.has(errorCode)) {
      sql = `WITH alvo AS (
               UPDATE envios SET status='falha', erro_tipo='permanente', erro_codigo=$2, erro_mensagem=$3, atualizado_em=now()
               WHERE provider_message_id=$1 AND canal='whatsapp' AND status NOT IN ('entregue','falha')
               RETURNING destino
             )
             INSERT INTO supressao (canal, destino, motivo)
             SELECT 'whatsapp', destino, 'invalido' FROM alvo
             ON CONFLICT (canal, destino) DO NOTHING;`;
      params = [providerMessageId, errorCode, errorMsg];
    } else if (errorCode === '131047') {
      sql = `UPDATE envios SET status='falha', erro_tipo='permanente', erro_codigo=$2, erro_mensagem=$3, atualizado_em=now()
             WHERE provider_message_id=$1 AND canal='whatsapp' AND status NOT IN ('entregue','falha');`;
      params = [providerMessageId, errorCode, errorMsg];
    } else if (CODIGOS_QUALIDADE.has(errorCode)) {
      sql = backoffSql();
      params = [providerMessageId, errorCode, errorMsg];
      pausarCampanha = true;
    } else if (CODIGOS_TEMPORARIOS.has(errorCode)) {
      sql = backoffSql();
      params = [providerMessageId, errorCode, errorMsg];
    } else {
      sql = backoffSql();
      params = [providerMessageId, errorCode || 'desconhecido', errorMsg || 'codigo nao mapeado'];
    }
  }
  // 'sent' e 'read': apenas registrar — já coberto pelo log em eventos_webhook; sql fica no-op.

  out.push({ json: { valid: true, providerMessageId, status, errorCode, sql, params, pausarCampanha } });
}
return out;

