const crypto = require('crypto');

const item = items[0];
const rawB64 = item.binary && item.binary.data ? item.binary.data.data : null;
const rawBody = rawB64 ? Buffer.from(rawB64, 'base64') : null;

const headers = item.json.headers || {};
const timestamp = headers['x-twilio-email-event-webhook-timestamp'];
const signature = headers['x-twilio-email-event-webhook-signature'];

const PUBLIC_KEY_PEM = `-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEatxLRAgVvnVNbp8OS7YIdZEx5Kmu\n5I27nlrvGKxE7hhEnYAGiXoJMsieIk2e0WzuS6G9khi2oxct2EmgRK3Ymw==\n-----END PUBLIC KEY-----`;

function verify() {
  if (rawBody === null || !timestamp || !signature) return false;
  try {
    const publicKey = crypto.createPublicKey({ key: PUBLIC_KEY_PEM, format: 'pem' });
    const signedPayload = Buffer.concat([Buffer.from(String(timestamp), 'utf8'), rawBody]);
    const sigBuf = Buffer.from(signature, 'base64');
    return crypto.verify('sha256', signedPayload, publicKey, sigBuf);
  } catch (e) {
    return false;
  }
}

const valid = verify();

let eventos = [];
try {
  const parsed = item.json.body ?? JSON.parse(rawBody ? rawBody.toString('utf8') : '[]');
  eventos = Array.isArray(parsed) ? parsed : [];
} catch (e) {
  eventos = [];
}

return [{ json: { valid, eventos } }];

