const prev = $('Verificar Assinatura SendGrid').first().json;
const valid = prev.valid;
const eventos = prev.eventos || [];

if (!valid || eventos.length === 0) {
  return [{ json: { valid, sql: 'SELECT 0 AS no_op;', params: [], pausarCampanha: false } }];
}

function backoffSql() {
  return `UPDATE envios SET
            status = CASE WHEN tentativas >= 5 THEN 'falha' ELSE 'pendente' END,
            erro_tipo = CASE WHEN tentativas >= 5 THEN 'permanente' ELSE 'temporario' END,
            erro_codigo = $2, erro_mensagem = $3,
            agendado_para = CASE tentativas
              WHEN 1 THEN now() + interval '5 minutes'
              WHEN 2 THEN now() + interval '15 minutes'
              WHEN 3 THEN now() + interval '1 hour'
              WHEN 4 THEN now() + interval '4 hours'
              ELSE now() + interval '12 hours'
            END,
            atualizado_em = now()
          WHERE id = $1 AND canal = 'email' AND status NOT IN ('entregue','falha');`;
}

const out = [];
for (const ev of eventos) {
  // envio_id vem de custom_args, setado no momento do envio (03-disparar-email) — é a
  // correlação confiável. sg_message_id NÃO bate exatamente com o X-Message-Id retornado
  // no envio (a SendGrid concatena sufixos), então não usamos ele para correlacionar.
  const envioId = ev.envio_id ? parseInt(ev.envio_id, 10) : null;
  const tipo = ev.event;
  const bounceType = ev.type || null; // em eventos "bounce": 'bounce' (hard) | 'blocked' (soft)

  let sql = 'SELECT 0 AS no_op;';
  let params = [];
  let pausarCampanha = false;

  if (!envioId) {
    out.push({ json: { valid: true, envioId: null, tipo, sql, params, pausarCampanha } });
    continue;
  }

  if (tipo === 'delivered') {
    sql = `UPDATE envios SET status='entregue', entregue_em=now(), atualizado_em=now()
           WHERE id=$1 AND canal='email' AND status NOT IN ('entregue','falha');`;
    params = [envioId];
  } else if (tipo === 'open') {
    sql = `UPDATE envios SET aberto_em = COALESCE(aberto_em, now()), atualizado_em=now()
           WHERE id=$1 AND canal='email';`;
    params = [envioId];
  } else if (tipo === 'bounce' && bounceType === 'bounce') {
    sql = `WITH alvo AS (
             UPDATE envios SET status='falha', erro_tipo='permanente', erro_codigo='bounce_hard',
                    erro_mensagem=$2, atualizado_em=now()
             WHERE id=$1 AND canal='email' AND status NOT IN ('entregue','falha')
             RETURNING destino
           )
           INSERT INTO supressao (canal, destino, motivo)
           SELECT 'email', destino, 'hard_bounce' FROM alvo
           ON CONFLICT (canal, destino) DO NOTHING;`;
    params = [envioId, (ev.reason || '').toString().slice(0, 500)];
  } else if (tipo === 'dropped') {
    sql = `WITH alvo AS (
             UPDATE envios SET status='falha', erro_tipo='permanente', erro_codigo='dropped',
                    erro_mensagem=$2, atualizado_em=now()
             WHERE id=$1 AND canal='email' AND status NOT IN ('entregue','falha')
             RETURNING destino
           )
           INSERT INTO supressao (canal, destino, motivo)
           SELECT 'email', destino, 'invalido' FROM alvo
           ON CONFLICT (canal, destino) DO NOTHING;`;
    params = [envioId, (ev.reason || '').toString().slice(0, 500)];
  } else if (tipo === 'spamreport') {
    sql = `WITH alvo AS (
             UPDATE envios SET status='falha', erro_tipo='permanente', erro_codigo='reclamacao',
                    erro_mensagem='complaint', atualizado_em=now()
             WHERE id=$1 AND canal='email' AND status NOT IN ('entregue','falha')
             RETURNING destino
           )
           INSERT INTO supressao (canal, destino, motivo)
           SELECT 'email', destino, 'reclamacao' FROM alvo
           ON CONFLICT (canal, destino) DO NOTHING;`;
    params = [envioId];
  } else if (tipo === 'unsubscribe' || tipo === 'group_unsubscribe') {
    sql = `WITH alvo AS (
             UPDATE envios SET status='suprimido', atualizado_em=now()
             WHERE id=$1 AND canal='email' AND status = 'pendente'
             RETURNING destino
           )
           INSERT INTO supressao (canal, destino, motivo)
           SELECT 'email', destino, 'descadastro' FROM alvo
           ON CONFLICT (canal, destino) DO NOTHING;`;
    params = [envioId];
  } else if (tipo === 'bounce' || tipo === 'deferred') {
    // 'bounce' com type desconhecido (não veio 'bounce' nem 'blocked' claramente) ou
    // 'deferred': trata como temporário — mais seguro que suprimir um contato válido à toa.
    sql = backoffSql();
    params = [envioId, tipo, (ev.reason || 'sem detalhe').toString().slice(0, 500)];
  }
  // 'processed', 'click' e tipos não mapeados: sql fica no-op (já registrado em eventos_webhook).

  out.push({ json: { valid: true, envioId, tipo, sql, params, pausarCampanha } });
}
return out;
